window.AUTH=window.AUTH||{};window.AUTH["17-1268"]={"d":"17-1268","id":"2019/17-1268","n":"Opati v. Republic of Sudan","briefs":[{"k":"petitioner","label":"Brief of petitioners Monicah Okoba Opati, et al.","date":"2019-09-17","url":"https://www.supremecourt.gov/DocketPDF/17/17-1268/116092/20190917165629051_Brief.pdf","side":"pet","n":31},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2019-09-24","url":"https://www.supremecourt.gov/DocketPDF/17/17-1268/116903/20190924182439063_17-1268tsacUnitedStates.pdf","side":"us","n":51},{"k":"respondent","label":"Brief of respondents Republic of Sudan, et al.","date":"2019-11-22","url":"https://www.supremecourt.gov/DocketPDF/17/17-1268/123381/20191122141432868_Brief%20for%20Respondents_17-1268.pdf","side":"res","n":61},{"k":"reply","label":"Reply of petitioners Monicah Okoba Opati, et al.","date":"2019-12-23","url":"https://www.supremecourt.gov/DocketPDF/17/17-1268/126578/20191223144202246_Reply%20Brief%20TO%20FILE.pdf","side":"pet","n":28}],"opinion":"https://www.supremecourt.gov/opinions/preliminaryprint/590US1PP_web.pdf#page=434","tr":true,"items":[{"t":"case","label":"Argentine Republic v. Amerada Hess Shipping Corp.","cite":"488 U.S. 428","y":1989,"id":"1988/87-1372","sc":1,"by":{"0":"40"}},{"t":"case","label":"Bakhtiar v. Islamic Republic of Iran","cite":"668 F.3d 773","y":2012,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/668/773/","by":{"0":"44","3":"15"},"q":[{"src":"brief","b":0,"text":"set forth three options for plaintiffs with pending cases to seek punitive damages against foreign nations.","cite":"668 F.3d 773, 774"},{"src":"brief","b":3,"text":"plaintiffs with pending cases could file related actions under § 1605A within 60 days of enactment of the new law or within 60 days of judgment in their original case, whichever was later.","cite":"668 F.3d 773, 774"},{"src":"brief","b":3,"text":"who appropriately invoked state or foreign law for their cause of action … would not be able to obtain punitive damages.","cite":"668 F.3d at 775"}]},{"t":"case","label":"Bank Markazi v. Peterson","cite":"136 S. Ct. 1310","y":2016,"id":"2015/14-770","sc":1,"by":{"0":"25-26, 33","1":"20"},"q":[{"src":"brief","b":0,"text":"the Constitution places on retroactive legislation,","cite":"136 S.Ct. at 1324"},{"src":"brief","b":1,"text":"is not a sufficient reason for a court to fail to give that law its intended scope.","cite":"136 S. Ct. 1310, 1325"}]},{"t":"case","label":"Cicippio-Puleo v. Islamic Republic of Iran","cite":"353 F.3d 1024","y":2004,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/353/1024/","by":{"0":"8, 11","1":"3, 26, 27","2":"8, 43, 44"},"q":[{"src":"brief","b":0,"text":"neither 28 U.S.C. § 1605(a)(7) nor the Flatow Amendment, nor the two considered in tandem, creates a private right of action against a foreign government.","cite":"353 F.3d 1024, 1033"},{"src":"brief","b":1,"text":"merely waive[d] the [ jurisdictional] immunity of a foreign state","cite":"353 F.3d 1024, 1033"},{"src":"brief","b":2,"text":"for money damages which may include economic damages, solatium, pain, and suffering, and punitive damages.","cite":"353 F.3d 1024, 1033"}]},{"t":"case","label":"City of Sherrill v. Oneida Indian Nation of N.Y.","cite":"544 U.S. 197","y":2005,"id":"2004/03-855","sc":1,"by":{"0":"55","3":"17"}},{"t":"case","label":"Dames & Moore v. Regan","cite":"453 U.S. 654","y":1981,"id":"1980/80-2078","sc":1,"by":{"0":"32"}},{"t":"case","label":"Eisenfeld v. Islamic Republic of Iran","cite":"172 F. Supp. 2d 1","y":2000,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/172/1/","by":{"0":"5","1":"23"}},{"t":"case","label":"Fernandez-Vargas v. Gonzales","cite":"548 U.S. 30","y":2006,"id":"2005/04-1376","sc":1,"by":{"0":"38-39","1":"15, 22"},"q":[{"src":"brief","b":1,"text":"owing to the ‘absen[ce of ] a clear indication from Congress that it intended such a result,’","cite":"548 U.S. 30, 37-38"}]},{"t":"case","label":"Flatow v. Islamic Republic of Iran","cite":"999 F. Supp. 1","y":1998,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp./999/1/","by":{"0":"5, 31, 43","1":"23"},"q":[{"src":"argument","who":"Chief Justice Roberts","text":"In 1996 Congress enacted the Flatow amendment which, which explicitly provided for punitive damages for acts of state-sponsored terrorism. But still Sudan continued to harbor Al Qaeda."},{"src":"argument","who":"Justice Kagan","text":"And prior to 2004, many courts in D.C. had awarded punitive damages in cases under the Flatow Amendment. One of those cases was a case called Acree versus Iraq that this Court addressed in Iraq versus Beaty, it was a 959 million dollar judgment that included 300 million dollars of punitive damages."},{"src":"argument","who":"Justice Breyer","text":"But that -- wouldn't that be a little weird? In other words, you brought it under 1605A before what's called the Flatow Amendment, is this -- I don't know what you're --"}]},{"t":"case","label":"Franchise Tax Bd. of Cal. v. Hyatt","cite":"139 S. Ct. 1485","y":2019,"id":"2018/17-1299","sc":1,"by":{"0":"25"}},{"t":"case","label":"Cited Authorities Page Franklin v. Gwinnett Cnty. Public Schools","cite":"503 U.S. 60","y":1992,"id":"1991/90-918","sc":1,"by":{"0":"47"}},{"t":"case","label":"Hughes Aircraft Co. v. United States ex rel. Schumer","cite":"520 U.S. 939","y":1997,"id":"1996/95-1340","sc":1,"by":{"0":"38","1":"18, 30, 32","2":"36, 39"},"q":[{"src":"brief","b":1,"text":"even if they happen sometimes to affect them.","cite":"520 U.S. at 951"}]},{"t":"case","label":"Jenco v. Islamic Republic of Iran","cite":"154 F. Supp. 2d 27","y":2001,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/154/27/","by":{"0":"5","1":"23"}},{"t":"case","label":"Landgraf v. USI Film Prods.","cite":"511 U.S. 244","y":1994,"id":"1993/92-757","sc":1,"by":{"0":"passim","1":"passim","2":"passim","3":"1, 2, 3, 5, 6, 7, 10, 11, 12, 16, 18"},"q":[{"src":"brief","b":1,"text":"If Congress has clearly spoken, then ‘there is no need to resort to judicial default rules,’ and the court must apply the statute as written.","cite":"511 U.S. at 280"},{"src":"brief","b":1,"text":"evaluate whether the legislation ‘operate[s] retroactively,’ as it does if it ‘would impair rights a party possessed when he acted, increase a party’s liability for past conduct, or impose new duties with respect to transactions already completed.’","cite":"511 U.S. at 280"},{"src":"brief","b":2,"text":"The extent of a party’s liability, in the civil context as well as the criminal, is an important legal consequence that cannot be ignored.","cite":"511 U.S. at 283"},{"src":"brief","b":2,"text":"[T]he FSIA merely opens United States courts to plaintiffs with pre-existing claims against foreign states; the Act neither ‘increase[s those states’] liability for past conduct’ nor ‘impose[s] new duties with respect to transactions already completed.’","cite":"511 U.S. at 280"},{"src":"brief","b":3,"text":"Congress has expressly prescribed the [2008 amendments’] proper reach.","cite":"511 U.S. at 280"},{"src":"brief","b":3,"text":"is no need to resort to judicial default rules.","cite":"511 U.S. at 280"},{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"is deeply rooted in our jurisprudence, and embodies a legal doctrine centuries older than our Republic.","cite":"511 U. S. 244, 265"},{"src":"argument","who":"Chief Justice Roberts","text":"But to impose punitive damages, Sudan argues, somehow would violate principles of fundamental fairness embodied in the Landgraf presumption."},{"src":"argument","who":"Justice Alito","text":"So if we just apply the Landgraf test, what would be wrong with saying if Congress wants to make punitive damages retroactive, it has to say so expressly?"},{"src":"argument","who":"Justice Ginsburg","text":"McGILL: I'm not -- I'm not aware that Sudan is wrong as to what it said, but the Court was very clear in Landgraf that if the 1990 bill had been enacted, that would have been sufficient."}]},{"t":"case","label":"Lewis v. Clarke","cite":"137 S. Ct. 1285","y":2017,"id":"2016/15-1500","sc":1,"by":{"0":"55"}},{"t":"case","label":"North Star Steel Co. v. Thomas","cite":"515 U.S. 29","y":1995,"id":"1994/94-834","sc":1,"by":{"0":"52"}},{"t":"case","label":"Owens v. Republic of Sudan","cite":"374 F. Supp. 2d 1","y":2005,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/374/1/","by":{"0":"7"}},{"t":"case","label":"Owens v. Republic of Sudan","cite":"412 F. Supp. 2d 99","y":2006,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/412/99/","by":{"0":"7","1":"6"}},{"t":"case","label":"Owens v. Republic of Sudan","cite":"531 F.3d 884","y":2008,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/531/884/","by":{"0":"7"}},{"t":"case","label":"Republic of Argentina v. NML Capital, Ltd.","cite":"573 U.S. 134","y":2014,"id":"2013/12-842","sc":1,"by":{"0":"28"},"q":[{"src":"brief","b":0,"text":"comprehensive set of legal standards governing claims of immunity in every civil action against a foreign state. … Thus, any sort of immunity defense made by a foreign sovereign in an American court must stand on the Act’s text. Or it must fall.","cite":"573 U.S. 134, 141-42"}]},{"t":"case","label":"Cited Authorities Page Republic of Austria v. Altmann","cite":"541 U.S. 677","y":2004,"id":"2003/03-13","sc":1,"by":{"0":"passim","1":"passim","2":"passim","3":"1, 2, 5, 6, 7, 8, 9, 10, 18"},"q":[{"src":"brief","b":0,"text":"[F]oreign sovereigns have no right to immunity in our courts.","cite":"541 U.S. at 688"},{"src":"brief","b":0,"text":"[t]hroughout history, courts have resolved questions of foreign sovereign immunity by deferring to the decisions of the political branches … on whether to take jurisdiction.","cite":"541 U.S. at 696"},{"src":"brief","b":1,"text":"obvious that the imposition of punitive damages under the new federal cause of action in § 1605A(c) operates retroactively because it increases Sudan’s liability for past conduct.","cite":"541 U.S. 677"},{"src":"brief","b":1,"text":"the authorization of punitive damages ‘adheres to the cause of action’ under § 1605A(c), making it ‘essentially substantive.’","cite":"541 U.S. at 695 n.15"},{"src":"brief","b":2,"text":"create or modify any causes of action.","cite":"541 U.S. at 695 n.15"},{"src":"brief","b":2,"text":"read a statute substantially increasing the monetary liability of a private party to apply to conduct occurring before the statute’s enactment.","cite":"541 U.S. 677"},{"src":"brief","b":3,"text":"deferr[ed] to the decisions of the political branches.","cite":"541 U.S. at 696"},{"src":"brief","b":3,"text":"create or modify any causes of action","cite":"541 U.S. at 695 n.15"}]},{"t":"case","label":"Republic of Iraq v. Beaty","cite":"556 U.S. 848","y":2009,"id":"2008/07-1090","sc":1,"by":{"0":"32, 54","1":"21"},"q":[{"src":"brief","b":0,"text":"was identical in all material respects but for the addition of Presidential waiver authority.","cite":"556 U.S. at 853"}]},{"t":"case","label":"Republic of Sudan v. Owens","cite":"194 A.3d 38","y":2018,"court":"D.C.","url":"https://www.courtlistener.com/c/A.3d/194/38/","by":{"0":"16"}},{"t":"case","label":"Rimkus v. Islamic Republic of Iran","cite":"750 F. Supp. 2d 163","y":2010,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/750/163/","by":{"0":"45","3":"15"},"q":[{"src":"brief","b":3,"text":"to ensure that plaintiffs who had obtained compensatory relief against terrorist-defendants could return to seek punitive damages against those same defendants.","cite":"750 F. Supp. 2d 163, 179"}]},{"t":"case","label":"Rubin v. Islamic Republic of Iran","cite":"138 S. Ct. 816","y":2018,"id":"2017/16-534","sc":1,"by":{"0":"23, 46","2":"22, 58"}},{"t":"case","label":"SAS Institute Inc. v. Iancu","cite":"138 S. Ct. 1348","y":2018,"id":"2017/16-969","sc":1,"by":{"0":"47"}},{"t":"case","label":"Scott v. Donald","cite":"165 U.S. 58","y":1897,"id":"scdb/1896-231","sc":1,"by":{"0":"31"}},{"t":"case","label":"United States v. Rahman","cite":"189 F.3d 88","y":1999,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/189/88/","by":{"0":"6"}},{"t":"case","label":"Verlinden B.V. v. Central Bank of Nigeria","cite":"461 U.S. 480","y":1983,"id":"1982/81-920","sc":1,"by":{"0":"27, 37-38, 41","1":"16, 17","2":"5, 36","3":"9"},"q":[{"src":"brief","b":0,"text":"this Court consistently has deferred to the decisions of the political branches ... on whether to take jurisdiction over actions against foreign sovereigns and their instrumentalities.","cite":"461 U.S. 480, 486"},{"src":"brief","b":1,"text":"transfer[red] primary responsibility for immunity determinations from the Executive to the Judicial Branch.","cite":"461 U.S. 480, 487-488"},{"src":"brief","b":1,"text":"‘the standards governing foreign sovereign immunity as an aspect of substantive federal law.’","cite":"461 U.S. at 497"},{"src":"argument","who":"Mr. Curran","text":"I do know it was complicated by the Verlinden decision, which said it established some substantive aspects of federal common law. But, in any event, Altmann was limited to the FSIA as it existed at the time, and that was pre-2008."}]},{"t":"case","label":"Brief for the United States, Acree v. Republic of Iraq","cite":"2005 WL 682164","y":2005,"court":"Mar. 21","by":{"0":"26, 29-30"}},{"t":"case","label":"Brief for the United States, Republic of Austria v. Altmann","cite":"2003 WL 22811828","y":2003,"court":"Nov. 14","by":{"0":"37"}},{"t":"case","label":"AT&T Corp. v. Hulteen","cite":"556 U.S. 701","y":2009,"id":"2008/07-543","sc":1,"by":{"1":"22","2":"47"}},{"t":"case","label":"Ditullio v. Boehm","cite":"662 F.3d 1091","y":2011,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/662/1091/","by":{"1":"25"}},{"t":"case","label":"Foger ty v. Fantasy, Inc.","cite":"510 U.S. 517","y":1994,"id":"1993/92-1750","sc":1,"by":{"1":"24"}},{"t":"case","label":"(III) Cases—Continued: Gross v. Weber","cite":"186 F.3d 1089","y":1999,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/186/1089/","by":{"1":"25, 26"},"q":[{"src":"argument","who":"Chief Justice Roberts","text":"In the subsection entitled, \"Application to Pending Cases,\" Congress set forth two categories of cases, prior actions and related actions, each of which were unmistakably directed at past acts of terrorism."}]},{"t":"case","label":"INS v. St. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"by":{"1":"15, 22","2":"47"}},{"t":"case","label":"Koch v. SEC","cite":"793 F.3d 147","y":2015,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/793/147/","by":{"1":"26"}},{"t":"case","label":"Lindh v. Murphy","cite":"521 U.S. 320","y":1997,"id":"1996/96-6298","sc":1,"by":{"1":"22","2":"41, 46, 47","3":"13"},"q":[{"src":"brief","b":2,"text":"so clear that it could sustain only one interpretation.","cite":"521 U.S. 320, 328 n.4"},{"src":"brief","b":2,"text":"Landgraf suggested that the [1990 bill’s language] might possibly have qualified as a clear statement for retroactive effect.","cite":"521 U.S. 320, 328 n.4"},{"src":"argument","who":"Mr. Curran","text":"It's Lindh. It's St. Cyr. All of these cases say if you're going to imply -- to -- to apply punishment or significant increased damages retroactively, Congress, you got to say it pretty clearly."}]},{"t":"law","label":"and rules: Aimee’s Law, Pub. L. No. 106-386","url":"https://www.govinfo.gov/link/plaw/106/public/386","by":{"1":"23, 25","2":"6, 16"}},{"t":"law","label":"Pub. L. No. 104-132","url":"https://www.govinfo.gov/link/plaw/104/public/132","by":{"1":"2"}},{"t":"usc","label":"42 U.S.C. § 1981a","url":"https://www.law.cornell.edu/uscode/text/42/1981a","subs":["(a)"],"by":{"1":"15"}},{"t":"usc","label":"20 U.S.C. § 1681","url":"https://www.law.cornell.edu/uscode/text/20/1681","by":{"1":"25"}},{"t":"usc","label":"28 U.S.C. § 1605","url":"https://www.law.cornell.edu/uscode/text/28/1605","subs":["(a)(7)","(a)(7)(2000)","(a)(7)(2006)","(e)"],"stext":{"head":"§1605. General exceptions to the jurisdictional immunity of a foreign state","paras":[[0,"(a) A foreign state shall not be immune from the jurisdiction of courts of the United States or of the States in any case—"],[1,"(1) in which the foreign state has waived its immunity either explicitly or by implication, notwithstanding any withdrawal of the waiver which the foreign state may purport to effect except in accordance with the terms of the waiver;"],[1,"(2) in which the action is based upon a commercial activity carried on in the United States by the foreign state; or upon an act performed in the United States in connection with a commercial activity of the foreign state elsewhere; or upon an act outside the territory of the United States in connection with a commercial activity of the foreign state elsewhere and that act causes a direct effect in the United States;"],[1,"(3) in which rights in property taken in violation of international law are in issue and that property or any property exchanged for such property is present in the United States in connection with a commercial activity carried on in the United States by the foreign state; or that property or any property exchanged for such property is owned or operated by an agency or instrumentality of the foreign state and that agency or instrumentality is engaged in a commercial activity in the United States;"],[1,"(4) in which rights in property in the United States acquired by succession or gift or rights in immovable property situated in the United States are in issue;"],[1,"(5) not otherwise encompassed in paragraph (2) above, in which money damages are sought against a foreign state for personal injury or death, or damage to or loss of property, occurring in the United States and caused by the tortious act or omission of that foreign state or of any official or employee of that foreign state while acting within the scope of his office or employment; except this paragraph shall not apply to—"],[2,"(A) any claim based upon the exercise or performance or the failure to exercise or perform a discretionary function regardless of whether the discretion be abused, or"],[2,"(B) any claim arising out of malicious prosecution, abuse of process, libel, slander, misrepresentation, deceit, or interference with contract rights; or"],[1,"(6) in which the action is brought, either to enforce an agreement made by the foreign state with or for the benefit of a private party to submit to arbitration all or any differences which have arisen or which may arise between the parties with respect to a defined legal relationship, whether contractual or not, concerning a subject matter capable of settlement by arbitration under the laws of the United States, or to confirm an award made pursuant to such an agreement to arbitrate, if (A) the arbitration takes place or is intended to take place in the United States, (B) the agreement or award is or may be governed by a treaty or other international agreement in force for the United States calling for the recognition and enforcement of arbitral awards, (C) the underlying claim, save for the agreement to arbitrate, could have been brought in a United States court under this section or section 1607, or (D) paragraph (1) of this subsection is otherwise applicable."],[0,"(b) A foreign state shall not be immune from the jurisdiction of the courts of the United States in any case in which a suit in admiralty is brought to enforce a maritime lien against a vessel or cargo of the foreign state, which maritime lien is based upon a commercial activity of the foreign state: Provided, That—"],[1,"(1) notice of the suit is given by delivery of a copy of the summons and of the complaint to the person, or his agent, having possession of the vessel or cargo against which the maritime lien is asserted; and if the vessel or cargo is arrested pursuant to process obtained on behalf of the party bringing the suit, the service of process of arrest shall be deemed to constitute valid delivery of such notice, but the party bringing the suit shall be liable for any damages sustained by the foreign state as a result of the arrest if the party bringing the suit had actual or constructive knowledge that the vessel or cargo of a foreign state was involved; and"],[1,"(2) notice to the foreign state of the commencement of suit as provided in section 1608 of this title is initiated within ten days either of the delivery of notice as provided in paragraph (1) of this subsection or, in the case of a party who was unaware that the vessel or cargo of a foreign state was involved, of the date such party determined the existence of the foreign state's interest."],[0,"(c) Whenever notice is delivered under subsection (b)(1), the suit to enforce a maritime lien shall thereafter proceed and shall be heard and determined according to the principles of law and rules of practice of suits in rem whenever it appears that, had the vessel been privately owned and possessed, a suit in rem might have been maintained. A decree against the foreign state may include costs of the suit and, if the decree is for a money judgment, interest as ordered by the court, except that the court may not award judgment against the foreign state in an amount greater than the value of the vessel or cargo upon which the maritime lien arose. Such value shall be determined as of the time notice is served under subsection (b)(1). Decrees shall be subject to appeal and revision as provided in other cases of admiralty and maritime jurisdiction. Nothing shall preclude the plaintiff in any proper case from seeking relief in personam in the same action brought to enforce a maritime lien as provided in this section."],[0,"(d) A foreign state shall not be immune from the jurisdiction of the courts of the United States in any action brought to foreclose a preferred mortgage, as defined in section 31301 of title 46. Such action shall be brought, heard, and determined in accordance with the provisions of chapter 313 of title 46 and in accordance with the principles of law and rules of practice of suits in rem, whenever it appears that had the vessel been privately owned and possessed a suit in rem might have been maintained."],[0,"[(e), (f) Repealed. Pub. L. 110–181, div. A, title X, §1083(b)(1)(B), Jan. 28, 2008, 122 Stat. 341.]"],[0,"(g) Limitation on Discovery.—"],[1,"(1) In general.—(A) Subject to paragraph (2), if an action is filed that would otherwise be barred by section 1604, but for section 1605A or section 1605B, the court, upon request of the Attorney General, shall stay any request, demand, or order for discovery on the United States that the Attorney General certifies would significantly interfere with a criminal investigation or prosecution, or a national security operation, related to the incident that gave rise to the cause of action, until such time as the Attorney General advises the court that such request, demand, or order will no longer so interfere."],[1,"(B) A stay under this paragraph shall be in effect during the 12-month period beginning on the date on which the court issues the order to stay discovery. The court shall renew the order to stay discovery for additional 12-month periods upon motion by the United States if the Attorney General certifies that discovery would significantly interfere with a criminal investigation or prosecution, or a national security operation, related to the incident that gave rise to the cause of action."],[1,"(2) Sunset.—(A) Subject to subparagraph (B), no stay shall be granted or continued in effect under paragraph (1) after the date that is 10 years after the date on which the incident that gave rise to the cause of action occurred."],[1,"(B) After the period referred to in subparagraph (A), the court, upon request of the Attorney General, may stay any request, demand, or order for discovery on the United States that the court finds a substantial likelihood would—"],[2,"(i) create a serious threat of death or serious bodily injury to any person;"],[2,"(ii) adversely affect the ability of the United States to work in cooperation with foreign and international law enforcement agencies in investigating violations of United States law; or"],[2,"(iii) obstruct the criminal case related to the incident that gave rise to the cause of action or undermine the potential for a conviction in such case."],[1,"(3) Evaluation of evidence.—The court's evaluation of any request for a stay under this subsection filed by the Attorney General shall be conducted ex parte and in camera."],[1,"(4) Bar on motions to dismiss.—A stay of discovery under this subsection shall constitute a bar to the granting of a motion to dismiss under rules 12(b)(6) and 56 of the Federal Rules of Civil Procedure."],[1,"(5) Construction.—Nothing in this subsection shall prevent the United States from seeking protective orders or asserting privileges ordinarily available to the United States."],[0,"(h) Jurisdictional Immunity for Certain Art Exhibition Activities.—"],[1,"(1) In general.—If—"],[2,"(A) a work is imported into the United States from any foreign state pursuant to an agreement that provides for the temporary exhibition or display of such work entered into between a foreign state that is the owner or custodian of such work and the United States or one or more cultural or educational institutions within the United States;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1605?type=usc&year=mostrecent&link-type=html"},"by":{"1":"23, 23, 3, 5, passim","2":"passim, 8, passim, 54"}},{"t":"usc","label":"28 U.S.C. § 1330","url":"https://www.law.cornell.edu/uscode/text/28/1330","by":{"1":"2"}},{"t":"usc","label":"28 U.S.C. § 1602","url":"https://www.law.cornell.edu/uscode/text/28/1602","stext":{"head":"§1602. Findings and declaration of purpose","paras":[[0,"The Congress finds that the determination by United States courts of the claims of foreign states to immunity from the jurisdiction of such courts would serve the interests of justice and would protect the rights of both foreign states and litigants in United States courts. Under international law, states are not immune from the jurisdiction of foreign courts insofar as their commercial activities are concerned, and their commercial property may be levied upon for the satisfaction of judgments rendered against them in connection with their commercial activities. Claims of foreign states to immunity should henceforth be decided by courts of the United States and of the States in conformity with the principles set forth in this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1602?type=usc&year=mostrecent&link-type=html"},"by":{"1":"2"},"q":[{"src":"brief","b":1,"text":"[c]laims of foreign states to immunity should henceforth be decided","cite":"28 U.S.C. 1602"}]},{"t":"usc","label":"28 U.S.C. § 1604","url":"https://www.law.cornell.edu/uscode/text/28/1604","stext":{"head":"§1604. Immunity of a foreign state from jurisdiction","paras":[[0,"Subject to existing international agreements to which the United States is a party at the time of enactment of this Act a foreign state shall be immune from the jurisdiction of the courts of the United States and of the States except as provided in sections 1605 to 1607 of this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1604?type=usc&year=mostrecent&link-type=html"},"by":{"1":"2","2":"5"}},{"t":"usc","label":"28 U.S.C. § 1605A","url":"https://www.law.cornell.edu/uscode/text/28/1605A","subs":["(a)","(a)(1)","(a)(2)(A)(i)","(a)(2)(A)(i)(II)","(c)","(a)(2)","(a)(2)(A)(ii)","(b)","(h)(7)"],"stext":{"head":"§1605A. Terrorism exception to the jurisdictional immunity of a foreign state","paras":[[0,"(a) In General.—"],[1,"(1) No immunity.—A foreign state shall not be immune from the jurisdiction of courts of the United States or of the States in any case not otherwise covered by this chapter in which money damages are sought against a foreign state for personal injury or death that was caused by an act of torture, extrajudicial killing, aircraft sabotage, hostage taking, or the provision of material support or resources for such an act if such act or provision of material support or resources is engaged in by an official, employee, or agent of such foreign state while acting within the scope of his or her office, employment, or agency."],[1,"(2) Claim heard.—The court shall hear a claim under this section if—"],[2,"(A)(i)(I) the foreign state was designated as a state sponsor of terrorism at the time the act described in paragraph (1) occurred, or was so designated as a result of such act, and, subject to subclause (II), either remains so designated when the claim is filed under this section or was so designated within the 6-month period before the claim is filed under this section; or"],[2,"(II) in the case of an action that is refiled under this section by reason of section 1083(c)(2)(A) of the National Defense Authorization Act for Fiscal Year 2008 or is filed under this section by reason of section 1083(c)(3) of that Act, the foreign state was designated as a state sponsor of terrorism when the original action or the related action under section 1605(a)(7) (as in effect before the enactment of this section) or section 589 of the Foreign Operations, Export Financing, and Related Programs Appropriations Act, 1997 (as contained in section 101(c) of division A of Public Law 104–208) was filed;"],[2,"(ii) the claimant or the victim was, at the time the act described in paragraph (1) occurred—"],[3,"(I) a national of the United States;"],[3,"(II) a member of the armed forces; or"],[3,"(III) otherwise an employee of the Government of the United States, or of an individual performing a contract awarded by the United States Government, acting within the scope of the employee's employment; and"],[2,"(iii) in a case in which the act occurred in the foreign state against which the claim has been brought, the claimant has afforded the foreign state a reasonable opportunity to arbitrate the claim in accordance with the accepted international rules of arbitration; or"],[2,"(B) the act described in paragraph (1) is related to Case Number 1:00CV03110 (EGS) in the United States District Court for the District of Columbia."],[0,"(b) Limitations.—An action may be brought or maintained under this section if the action is commenced, or a related action was commenced under section 1605(a)(7) (before the date of the enactment of this section) or section 589 of the Foreign Operations, Export Financing, and Related Programs Appropriations Act, 1997 (as contained in section 101(c) of division A of Public Law 104–208) not later than the latter of—"],[1,"(1) 10 years after April 24, 1996; or"],[1,"(2) 10 years after the date on which the cause of action arose."],[0,"(c) Private Right of Action.—A foreign state that is or was a state sponsor of terrorism as described in subsection (a)(2)(A)(i), and any official, employee, or agent of that foreign state while acting within the scope of his or her office, employment, or agency, shall be liable to—"],[1,"(1) a national of the United States,"],[1,"(2) a member of the armed forces,"],[1,"(3) an employee of the Government of the United States, or of an individual performing a contract awarded by the United States Government, acting within the scope of the employee's employment, or"],[1,"(4) the legal representative of a person described in paragraph (1), (2), or (3),"],[0,"for personal injury or death caused by acts described in subsection (a)(1) of that foreign state, or of an official, employee, or agent of that foreign state, for which the courts of the United States may maintain jurisdiction under this section for money damages. In any such action, damages may include economic damages, solatium, pain and suffering, and punitive damages. In any such action, a foreign state shall be vicariously liable for the acts of its officials, employees, or agents."],[0,"(d) Additional Damages.—After an action has been brought under subsection (c), actions may also be brought for reasonably foreseeable property loss, whether insured or uninsured, third party liability, and loss claims under life and property insurance policies, by reason of the same acts on which the action under subsection (c) is based."],[0,"(e) Special Masters.—"],[1,"(1) In general.—The courts of the United States may appoint special masters to hear damage claims brought under this section."],[1,"(2) Transfer of funds.—The Attorney General shall transfer, from funds available for the program under section 1404C of the Victims of Crime Act of 1984 (42 U.S.C. 10603c),1 to the Administrator of the United States district court in which any case is pending which has been brought or maintained under this section such funds as may be required to cover the costs of special masters appointed under paragraph (1). Any amount paid in compensation to any such special master shall constitute an item of court costs."],[0,"(f) Appeal.—In an action brought under this section, appeals from orders not conclusively ending the litigation may only be taken pursuant to section 1292(b) of this title."],[0,"(g) Property Disposition.—"],[1,"(1) In general.—In every action filed in a United States district court in which jurisdiction is alleged under this section, the filing of a notice of pending action pursuant to this section, to which is attached a copy of the complaint filed in the action, shall have the effect of establishing a lien of lis pendens upon any real property or tangible personal property that is—"],[2,"(A) subject to attachment in aid of execution, or execution, under section 1610;"],[2,"(B) located within that judicial district; and"],[2,"(C) titled in the name of any defendant, or titled in the name of any entity controlled by any defendant if such notice contains a statement listing such controlled entity."],[1,"(2) Notice.—A notice of pending action pursuant to this section shall be filed by the clerk of the district court in the same manner as any pending action and shall be indexed by listing as defendants all named defendants and all entities listed as controlled by any defendant."],[1,"(3) Enforceability.—Liens established by reason of this subsection shall be enforceable as provided in chapter 111 of this title."],[0,"(h) Definitions.—For purposes of this section—"],[1,"(1) the term \"aircraft sabotage\" has the meaning given that term in Article 1 of the Convention for the Suppression of Unlawful Acts Against the Safety of Civil Aviation;"],[1,"(2) the term \"hostage taking\" has the meaning given that term in Article 1 of the International Convention Against the Taking of Hostages;"],[1,"(3) the term \"material support or resources\" has the meaning given that term in section 2339A of title 18;"],[1,"(4) the term \"armed forces\" has the meaning given that term in section 101 of title 10;"],[1,"(5) the term \"national of the United States\" has the meaning given that term in section 101(a)(22) of the Immigration and Nationality Act (8 U.S.C. 1101(a)(22));"],[1,"(6) the term \"state sponsor of terrorism\" means a country the government of which the Secretary of State has determined, for purposes of section 6(j) of the Export Administration Act of 1979 (50 U.S.C. App. 2405(j)),1 section 620A of the Foreign Assistance Act of 1961 (22 U.S.C. 2371), section 40 of the Arms Export Control Act (22 U.S.C. 2780), or any other provision of law, is a government that has repeatedly provided support for acts of international terrorism; and"],[1,"(7) the terms \"torture\" and \"extrajudicial killing\" have the meaning given those terms in section 3 of the Torture Victim Protection Act of 1991 (28 U.S.C. 1350 note)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1605A?type=usc&year=mostrecent&link-type=html"},"by":{"1":"3, 3, 3, 3, 3, 3, 19, 33, 5, 20, 27, 4, 6, 18, 19, 11, 13, 4, 6, 13, 19, 32, 21","2":"passim, passim, 16, 21, 10, 4, 53, 58, 59, 17, 28, 29, passim, 21, 54","3":"23, 1, 14, 23, 21"},"q":[{"src":"brief","b":1,"text":"while acting within the scope of his or her office, employment, or agency.","cite":"28 U.S.C. 1605A(a)(1)"},{"src":"brief","b":1,"text":"economic damages, solatium, pain and suffering, and punitive damages.","cite":"28 U.S.C. 1605A(c)"},{"src":"brief","b":3,"text":"economic damages, solatium, pain and suffering, and punitive damages.","cite":"28 U.S.C. § 1605A(c)"},{"src":"argument","who":"Chief Justice Roberts","text":"Then the amendments say, in Section 1083(c)(1), \"The amendments made by this section shall apply to any claim arising under Section 1605A.\" Congress had said prior -- prior actions and related actions could file under this new 1605A, and now Congress is saying the amendments made by this section shall apply to any of those claims."},{"src":"argument","who":"Justice Kagan","text":"First is the prior actions provision, which for qualifying cases provided not only that an action could be restored under the new Section 1605A but also that the judgment itself shall be given effect as if it had been originally filed under 1605A(c)."},{"src":"argument","who":"Justice Alito","text":"And I guess the third point I would make is that once you acknowledge and concede that these state law claims are brought under Section 1605A, and -- and it should be emphasized that Petitioner's claims here have only ever been claims under Section 1605A."}]},{"t":"usc","label":"28 U.S.C. § 1606","url":"https://www.law.cornell.edu/uscode/text/28/1606","stext":{"head":"§1606. Extent of liability","paras":[[0,"As to any claim for relief with respect to which a foreign state is not entitled to immunity under section 1605 or 1607 of this chapter, the foreign state shall be liable in the same manner and to the same extent as a private individual under like circumstances; but a foreign state except for an agency or instrumentality thereof shall not be liable for punitive damages; if, however, in any case wherein death was caused, the law of the place where the action or omission occurred provides, or has been construed to provide, for damages only punitive in nature, the foreign state shall be liable for actual or compensatory damages measured by the pecuniary injuries resulting from such death which were incurred by the persons for whose benefit the action was brought."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1606?type=usc&year=mostrecent&link-type=html"},"by":{"1":"3","2":"passim"},"q":[{"src":"brief","b":1,"text":"[a]s to any claim for relief with respect to which a foreign state is not entitled to immunity under section 1605 or 1607 of this chapter, * * * a foreign state except for an agency or instrumentality thereof shall not be liable for punitive damages.","cite":"28 U.S.C. 1606"},{"src":"argument","who":"Justice Alito","text":"So once you concede that the actions are under 1605A, Section 1606 has no application to them. The 1606 bar on punitive damages, as the D.C."},{"src":"argument","who":"Ms. Ross","text":"That's the language that Congress used, essentially, to describe the then current state of the FSIA in 2004, and we think it's still true with respect to the state law claims today, because plaintiffs would be proceeding, obviously, under state law and so section 1605A(a), which is the -- the exception to foreign sovereign immunity, and section 1606, which is the provision that previously barred punitive damages, neither of those create liability for punitive damages in the first instance."}]},{"t":"usc","label":"22 U.S.C. § 7101","url":"https://www.law.cornell.edu/uscode/text/22/7101","by":{"1":"25"}},{"t":"law","label":"Pub. L. No. 105-277","url":"https://www.govinfo.gov/link/plaw/105/public/277","by":{"1":"23","2":"9"}},{"t":"usc","label":"18 U.S.C. § 1595","url":"https://www.law.cornell.edu/uscode/text/18/1595","by":{"1":"25"}},{"t":"reg","label":"58 Fed. Reg. 52,523","url":"https://www.govinfo.gov/link/fr/58/52523","by":{"1":"5"}},{"t":"reg","label":"69 Fed. Reg. 58,793","url":"https://www.govinfo.gov/link/fr/69/58793","by":{"1":"21"}},{"t":"reg","label":"73 Fed. Reg. 6571","url":"https://www.govinfo.gov/link/fr/73/6571","by":{"1":"21"}},{"t":"case","label":"Agudas Chasidei Chabad of U.S. v. Russian Federation","cite":"528 F.3d 934","y":2008,"court":"D.C.Cir.","url":"https://www.courtlistener.com/c/F.3d/528/934/","by":{"2":"27-28"}},{"t":"case","label":"Alexander v. Sandoval","cite":"532 U.S. 275","y":2001,"id":"2000/99-1908","sc":1,"by":{"2":"59"}},{"t":"case","label":"Ashcroft v. Iqbal","cite":"556 U.S. 662","y":2009,"id":"2008/07-1015","sc":1,"by":{"2":"21","3":"20"}},{"t":"case","label":"Bettis v. Islamic Republic of Iran","cite":"315 F.3d 325","y":2003,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/315/325/","by":{"2":"5, 56"}},{"t":"case","label":"Bolivarian Republic of Venezuela v. Helmerich & Payne Int’l Drilling Co.","cite":"137 S. Ct. 1312","y":2017,"id":"2016/15-423","sc":1,"by":{"2":"19, 27, 28","3":"21"}},{"t":"case","label":"Bond v. United States","cite":"572 U.S. 844","y":2014,"id":"2013/12-158","sc":1,"by":{"2":"23"}},{"t":"case","label":"Bowen v. Georgetown Univ. Hosp.","cite":"488 U.S. 204","y":1988,"id":"1988/87-1097","sc":1,"by":{"2":"41"}},{"t":"case","label":"City of Rancho Palos Verdes v. Abrams","cite":"544 U.S. 113","y":2005,"id":"2004/03-1601","sc":1,"by":{"2":"59"}},{"t":"case","label":"Dolan v. U.S. Postal Serv.","cite":"546 U.S. 481","y":2006,"id":"2005/04-848","sc":1,"by":{"2":"22"}},{"t":"case","label":"Dole Food Co. v. Patrickson","cite":"538 U.S. 468","y":2003,"id":"2002/01-593","sc":1,"by":{"2":"39"},"q":[{"src":"brief","b":2,"text":"[T]he principal purpose of foreign sovereign immunity has never been to permit foreign states and their instrumentalities to shape their conduct in reliance on the promise of future immunity from suit in United States courts. Rather, such immunity reflects current political realities and relationships, and aims to give foreign states and their instrumentalities some present ‘protection from the inconvenience of suit as a gesture of comity.’","cite":"538 U.S. 468, 479"}]},{"t":"case","label":"Fort Bend Cty. v. Davis","cite":"139 S. Ct. 1843","y":2019,"id":"2018/18-525","sc":1,"by":{"2":"28, 29"},"q":[{"src":"brief","b":2,"text":"[a]n action may be brought or maintained under this section.","cite":"139 S. Ct. at 1848"}]},{"t":"case","label":"Graham & Foster v. Goodcell","cite":"282 U.S. 409","y":1931,"id":"scdb/1930-023","sc":1,"by":{"2":"47"}},{"t":"case","label":"Jesner v. Arab Bank, PLC","cite":"138 S. Ct. 1386","y":2018,"id":"2017/16-499","sc":1,"by":{"2":"22"},"q":[{"src":"brief","b":2,"text":"The TVPA — which is codified as a note following the [Alien Tort Statute] — creates an express cause of action for victims of torture and extrajudicial killing in violation of international law.","cite":"138 S. Ct. 1386, 1398"}]},{"t":"case","label":"Kadic v. Karadžić","cite":"70 F.3d 232","y":1995,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/70/232/","by":{"2":"23"}},{"t":"case","label":"Lake Country Estates, Inc. v. Tahoe Regional Planning Agency","cite":"440 U.S. 391","y":1979,"id":"1978/77-1327","sc":1,"by":{"2":"21"}},{"t":"case","label":"Leibovitch v. Islamic Republic of Iran","cite":"697 F.3d 561","y":2012,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/697/561/","by":{"2":"56"},"q":[{"src":"brief","b":2,"text":"pass-through approach [that] created a patch-work of inconsistent recovery for victims of terrorism and their families.","cite":"697 F.3d 561, 567-69"}]},{"t":"case","label":"Martin v. Hadix","cite":"527 U.S. 343","y":1999,"id":"1998/98-262","sc":1,"by":{"2":"46, 47","3":"13"},"q":[{"src":"argument","who":"Chief Justice Roberts","text":"That language, \"shall apply to\" -- \"to any claim,\" is virtually identical to the language in footnote 8 of Landgraf, \"shall apply to all proceedings,\" that -- that Landgraf described as an unambiguous directive and that the Court later in Martin versus Hadix described as unambiguously addressing the temporal reach of the statute."},{"src":"argument","who":"Justice Alito","text":"And this Court recognized -- but not -- not only in Landgraf, but later in Martin versus Hadix, that that was sufficient to unambiguously address the temporal reach of the statute."}]},{"t":"case","label":"Nat’l R.R. Passenger Corp. v. Nat’l Ass’n of R.R. Passengers","cite":"414 U.S. 453","y":1974,"id":"1973/72-1289","sc":1,"by":{"2":"59"}},{"t":"case","label":"P & V Enters. v. U.S. Army Corps of Eng’rs","cite":"516 F.3d 1021","y":2008,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/516/1021/","by":{"2":"30"},"q":[{"src":"brief","b":2,"text":"every civil action commenced against the United States","cite":"516 F.3d 1021, 1026"}]},{"t":"case","label":"Peterson v. Islamic Republic of Iran","cite":"515 F. Supp. 2d 25","y":2007,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/515/25/","by":{"2":"56"}},{"t":"case","label":"Samantar v. Yousuf","cite":"560 U.S. 305","y":2010,"id":"2009/08-1555","sc":1,"by":{"2":"22, 58"}},{"t":"case","label":"Soc’y for Propagation of the Gospel v. Wheeler","cite":"22 F. Cas. 756","y":1814,"court":"CCD N.H.","url":"https://www.courtlistener.com/c/F.%20Cas./22/756/","by":{"2":"35"},"q":[{"src":"brief","b":2,"text":"undoubtedly impose on employers found liable a ‘new disability’ in respect to past events.","cite":"22 F. Cas. 756, 767"}]},{"t":"case","label":"United States v. Wong","cite":"135 S. Ct. 1625","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/1625/","sc":1,"by":{"2":"28-29, 30"}},{"t":"case","label":"Wash. All. of Tech. Workers v. U.S. Dep’t of Homeland Sec.","cite":"892 F.3d 332","y":2018,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/892/332/","by":{"2":"30"}},{"t":"case","label":"Yee v. City of Escondido","cite":"503 U.S. 519","y":1992,"id":"1991/90-1947","sc":1,"by":{"2":"51"}},{"t":"usc","label":"28 U.S.C. § 1350","url":"https://www.law.cornell.edu/uscode/text/28/1350","stext":{"head":"§1350. Alien's action for tort","paras":[[0,"The district courts shall have original jurisdiction of any civil action by an alien for a tort only, committed in violation of the law of nations or a treaty of the United States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1350?type=usc&year=mostrecent&link-type=html"},"by":{"2":"6, 21-22, 54","3":"21"}},{"t":"usc","label":"28 U.S.C. § 1607","url":"https://www.law.cornell.edu/uscode/text/28/1607","by":{"2":"passim"}},{"t":"usc","label":"28 U.S.C. § 1610","url":"https://www.law.cornell.edu/uscode/text/28/1610","subs":["(g)"],"by":{"2":"11, 57, 58, 9"}},{"t":"usc","label":"28 U.S.C. § 2401","url":"https://www.law.cornell.edu/uscode/text/28/2401","subs":["(a)","(b)"],"by":{"2":"29, 30, 29"}},{"t":"law","label":"Pub. L. No. 104-208","url":"https://www.govinfo.gov/link/plaw/104/public/208","by":{"2":"8, 44"}},{"t":"law","label":"Pub. L. No. 102-256","url":"https://www.govinfo.gov/link/statute/106/73","by":{"2":"passim"}},{"t":"rule","label":"Fed. R. Civ. P. 60","url":"https://www.law.cornell.edu/rules/frcp/rule_60","subs":["(b)(4)","(b)(6)"],"by":{"2":"15, 15, 16"}},{"t":"case","label":"Day v. McDonough","cite":"547 U.S. 198","y":2006,"id":"2005/04-1324","sc":1,"by":{"3":"22"}},{"t":"case","label":"Edelman v. Lynchburg Coll.","cite":"535 U.S. 106","y":2002,"id":"2001/00-1072","sc":1,"by":{"3":"10"},"q":[{"src":"brief","b":3,"text":"that it expect[ed] its enactment[ ] to be interpreted in conformity with","cite":"535 U.S. 106, 117 n.13"}]},{"t":"case","label":"McQuiggin v. Perkins","cite":"569 U.S. 383","y":2013,"id":"2012/12-126","sc":1,"by":{"3":"9"},"q":[{"src":"brief","b":3,"text":"Congress legislate[d] against the backdrop of [this] existing [precedent].","cite":"569 U.S. 383, 398 n.3"}]},{"t":"case","label":"Musacchio v. United States","cite":"136 S. Ct. 709","y":2016,"id":"2015/14-1095","sc":1,"by":{"3":"22"}},{"t":"case","label":"Oliver v. Mustafa","cite":"929 A.2d 873","y":2007,"court":"D.C.","url":"https://www.courtlistener.com/c/A.2d/929/873/","by":{"3":"19"}},{"t":"case","label":"PGA Tour, Inc. v. Martin","cite":"532 U.S. 661","y":2001,"id":"2000/00-24","sc":1,"by":{"3":"14"},"q":[{"src":"brief","b":3,"text":"does not demonstrate ambiguity. It demonstrates breadth.","cite":"532 U.S. 661, 689"}]},{"t":"case","label":"Price v. Socialist People’s Libyan Arab Jamahiriya","cite":"294 F.3d 82","y":2002,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/294/82/","by":{"3":"6, 16"},"q":[{"src":"brief","b":3,"text":"foreign states are not ‘persons’ protected by the Fifth Amendment.","cite":"294 F.3d 82, 96"}]},{"t":"case","label":"Principality of Monaco v. Mississippi","cite":"292 U.S. 313","y":1934,"id":"scdb/1933-124","sc":1,"by":{"3":"6"}},{"t":"case","label":"South Carolina v. Katzenbach","cite":"383 U.S. 301","y":1966,"id":"1965/22_orig","sc":1,"by":{"3":"16"}},{"t":"case","label":"Wyeth v. Levine","cite":"555 U.S. 555","y":2009,"id":"2008/06-1249","sc":1,"by":{"3":"22"}},{"t":"case","label":"Zivotofsky ex rel. Zivotofsky v. Kerry","cite":"135 S. Ct. 2076","y":2015,"id":"2014/13-628","sc":1,"by":{"3":"8"},"q":[{"src":"brief","b":3,"text":"it is essential the congressional role in foreign affairs be understood and respected.","cite":"135 S. Ct. 2076, 2090"}]},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"3":"17"}},{"t":"usc","label":"22 U.S.C. § 8772","url":"https://www.law.cornell.edu/uscode/text/22/8772","by":{"3":"8"}},{"t":"law","label":"Pub. L. No. 114-122","url":"https://www.govinfo.gov/link/plaw/114/public/122","by":{"3":"7"}}]};